"""Scientific plots for material-coupon validation and enclosure sensitivity."""
import json,html,shutil
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

root=Path('test-results/stuffing');r=json.loads((root/'comparison.json').read_text());plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.grid':True,'grid.alpha':.2})
foam=next(x for x in r['materialSpectra'] if x['id']=='melamine-mlulb-2016')
fig,axes=plt.subplots(2,1,figsize=(11,8),layout='constrained',gridspec_kw={'height_ratios':[2,1]})
f=[v['frequency'] for v in foam['samples']];axes[0].semilogx(f,[v['absorption'] for v in foam['samples']],color='#b74230',label='Aegir: published NASA material fit');axes[0].scatter([v['frequency'] for v in r['nasaRows']],[v['measured'] for v in r['nasaRows']],facecolors='none',edgecolors='#222',s=25,label='Published measured hold-out specimen');axes[0].set(ylabel='Normal-incidence absorption coefficient',ylim=(0,1.03));axes[0].legend()
for ax in axes:ax.set_xscale('log');ax.set_xlim(50,4000);ax.axvspan(100,800,color='#2c8067',alpha=.08)
axes[1].axhspan(-.015,.015,color='#2c8067',alpha=.15,label='Declared graph-reading uncertainty +/-0.015');axes[1].plot([v['frequency'] for v in r['nasaRows']],[v['error'] for v in r['nasaRows']],marker='o',ms=3,color='#b74230');axes[1].axhline(0,color='#444',lw=.7);axes[1].set(xlabel='Frequency (Hz)',ylabel='Aegir minus measured');axes[1].legend(fontsize=9)
fig.suptitle('Melamine foam: comparison with a published measured specimen\n76.2 mm rigid-backed coupon; source fit unchanged',fontsize=15);fig.supxlabel('Shaded100–800 Hz: 21 markers, RMS0.0111, max0.0189. Assumed ambient rho1.21 kg/m³ / c343 m/s.\nThe fit and hold-out specimen came from the same foam slab. Near1kHz frame effects remain; this is not full-speaker validation.',fontsize=9);fig.savefig(root/'foam-validation.png',dpi=160);plt.close(fig)
fig,axes=plt.subplots(2,1,figsize=(11,8),layout='constrained')
for v in r['variants']:
 if v['id'] not in ['melamine-jca-2024','polyester-wm20-2018']:continue
 color='#1f7895' if v['id']=='melamine-jca-2024' else '#975d24';style='-' if v['placement']=='fill' else '--';label=v['name'].split(' · ')[0]+' / '+('full fill' if v['placement']=='fill' else '20 mm wall lining')
 axes[0].semilogx([p['frequency'] for p in v['points']],[p['impedance'] for p in v['points']],style,color=color,label=label);axes[1].semilogx([p['frequency'] for p in v['points']],[p['spl'] for p in v['points']],style,color=color)
axes[0].set(ylabel='Input impedance (ohm)');axes[0].legend(fontsize=9);axes[1].set(ylabel='Simulated SPL (dB)',xlabel='Frequency (Hz)')
for ax in axes:ax.set_xlim(20,800)
fig.suptitle('Enclosure sensitivity: material and placement change the result\nSame straight-line geometry and generic driver; no reference-curve fitting',fontsize=14);fig.supxlabel('These are predictions for substituted source materials, not measured speaker responses. Fibre bass extrapolation is unvalidated.\n1D wall lining uses equal-pressure homogenization, not a transverse-mode solution.',fontsize=9);fig.savefig(root/'placement-comparison.png',dpi=160);plt.close(fig)

def table(headers,rows):return '<table><tr>'+''.join('<th>'+html.escape(str(h))+'</th>' for h in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+html.escape(str(c))+'</td>' for c in row)+'</tr>' for row in rows)+'</table>'
metrics=table(['Retained marker band (Hz)','Points','Absorption RMS error','Maximum error'],[[str(v['bandHz']),v['count'],f"{v['rmse']:.5f}",f"{v['maxAbsoluteError']:.5f}"] for v in r['nasaMetrics']])
specimens=table(['Source specimen','Evidence','Qualification'],[[v['name'],v['evidence'],v['note']] for v in r['materialSpectra']])
doc=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aegir porous-material update</title><style>body{{background:#edf2f3;color:#23343d;font:16px/1.6 system-ui;margin:0}}main{{max-width:1120px;margin:auto;padding:35px 24px}}h1{{line-height:1.2}}h2{{margin-top:35px}}figure{{margin:25px 0;background:white;padding:14px}}img{{width:100%;height:auto}}table{{background:white;border-collapse:collapse;width:100%;font-size:14px}}td,th{{text-align:left;padding:12px;border-bottom:1px solid #d9e2e4}}.scope{{border-left:4px solid #a67b2c;background:#fff3d6;padding:18px}}a{{color:#176779}}</style><main><p>2026-11-03 · Aegir0.9.4 · Source-specific material validation</p><h1>Stuffing and acoustic foam: models, placement and checks</h1><p class="scope">The new models distinguish material properties from placement. Agreement below is with published measurements of a material coupon. It does not validate an entire loudspeaker, every foam grade, or a different batch.</p><h2>Measured foam check</h2><p>Allen &amp; Schiller's <a href="https://ntrs.nasa.gov/citations/20160010140">NASA2016 study</a> supplies measured airflow resistivity and an eight-coefficient propagation fit. Figure4 checks a separate76.2mm specimen not used for that fit, from the same foam slab. Aegir implements the source coefficients without fitting. Square-marker centres were extracted from original PDF vector objects. Assumed ambient rho1.21kg/m³ / c343m/s is explicit.</p>{metrics}<p>The declared graph reading uncertainty is ±0.015 absorption and ±1% frequency. Source measurement uncertainty is not asserted. The near1kHz frame-motion discrepancy remains. Retained markers extend only to about3kHz even though the source axis reaches10kHz.</p><figure><img src="foam-validation.png" alt="Predicted foam coupon absorption over published measured points, with residuals"></figure><h2>What changed</h2><p>Added Miki fibre propagation using measured airflow resistivity, five-parameter JCA for characterized foams, and source-defined empirical coefficients alongside existing JCAL and historical Hollofil models. Source-specimen presets retain provenance and range limitations. Wall lining has a thickness and an open air core; the3D steady-tone path places actual material cells near channel walls.</p><p>1D lining is a long-wavelength equal-pressure approximation. The3D recurrence matches the selected frequency only. It does not predict broadband porous-material startup; rigid frames, isotropy and adequate grid resolution remain assumptions.</p><h2>Same enclosure, different treatment</h2><p>These12 cases are unfitted sensitivities for six materials, each as full fill and20mm lining. The source specimens differ and should not be interpreted as interchangeable grades. The driver is the existing generic reference driver with schematic mechanical dimensions.</p><figure><img src="placement-comparison.png" alt="Four simulated material and placement cases in the same enclosure"></figure><h2>Source specimens</h2>{specimens}<h2>Regression checks</h2><p>The existing empty and stuffed King2006 sweeps retain identical2008 frequency predictions. The old stuffed opening-to-driver discrepancy remains {r['historicalStuffedOpeningToDriverRmsDb']:.3f}dB RMS. The previous non-monotonic3D cavity-volume error is not fixed by this work.</p><p>Independent Python complex arithmetic, JCA limits, reciprocal transfer matrices, shell placement and steady-tone recurrence checks accompany native UI save/reload, response and WebGPU foam-layer runs. See the <a href="verification.json">verification record</a> and <a href="comparison.json">full numeric comparison</a>. <a href="../../stuffing-research.md">Agent research record</a> · <a href="../../../MATERIALS.md">Equations and usage</a>.</p></main></html>'''
(root/'comparison.html').write_text(doc,encoding='utf-8')
dest=Path('docs/speaker-design/models/stuffing-upgrade');dest.mkdir(exist_ok=True)
for name in ['comparison.html','comparison.json','foam-validation.png','placement-comparison.png']:shutil.copy2(root/name,dest/name)
print(str(dest/'comparison.html'))
